  const gc = (typeof globalThis !== 'undefined' && globalThis.GAME_CONFIG) ||
             (typeof window !== 'undefined' && window.GAME_CONFIG) || null;
  return (gc && typeof gc.getCaps === 'function') ? gc.getCaps() : _FALLBACK_POKEDEX_CTRL_CAPS;
